package services

import (
	"context"
	"log/slog"
	"strings"

	tele "gopkg.in/telebot.v3"
)

// TopicEditor is the subset of *tele.Bot this plugin needs, kept as an interface so
// tests can fake Telegram without a real bot/API.
type TopicEditor interface {
	EditTopic(chat *tele.Chat, topic *tele.Topic) error
}

// TopicNamingPlugin asynchronously renames the Telegram forum topic a dialog lives in
// to something descriptive, generated by a cheap model from the dialog's first exchange
// (the user's first message and the assistant's reply to it) — mirroring how chat UIs
// auto-title a new conversation. Using the full exchange rather than just the user's
// message matters for vague first messages ("hey", a bare image) where the real topic
// only becomes clear once the assistant responds. It only ever acts on a dialog's very
// first turn (see TraceStore.IsFirstTurn) and is only attached to the chat Runner (see
// NewTextService) since a scheduled action's dialog already exists by definition and the
// General topic (dialogID 0) isn't a renameable forum topic at all.
type TopicNamingPlugin struct {
	trace  *TraceStore
	namer  *TopicNamer
	editor TopicEditor
}

func NewTopicNamingPlugin(trace *TraceStore, namer *TopicNamer, editor TopicEditor) *TopicNamingPlugin {
	return &TopicNamingPlugin{trace: trace, namer: namer, editor: editor}
}

func (p *TopicNamingPlugin) Name() string { return "topic_naming" }

var _ AfterTurnHook = (*TopicNamingPlugin)(nil)

// AfterTurn runs once finalResponse is ready, so the namer sees the whole first exchange
// rather than just the user's opening message. It never blocks the turn — the model call
// and Telegram edit both happen in a background goroutine.
func (p *TopicNamingPlugin) AfterTurn(ctx context.Context, rc *RunContext, finalResponse string) {
	if rc.TurnCtx.DialogID == 0 {
		return
	}
	userText := strings.TrimSpace(joinUserInputText(rc.Inputs))
	if userText == "" {
		return
	}
	isFirst, err := p.trace.IsFirstTurn(rc.TurnCtx.UserID, rc.TurnCtx.DialogID, len(rc.Inputs))
	if err != nil {
		slog.ErrorContext(ctx, "topic naming: failed to check turn position", "error", err)
		return
	}
	if !isFirst {
		return
	}

	chatID := rc.User.ChatId
	dialogID := rc.TurnCtx.DialogID
	exchange := buildTopicNamingInput(userText, finalResponse)
	go func() {
		name, err := p.namer.NameTopic(context.WithoutCancel(ctx), exchange)
		if err != nil || name == "" {
			return
		}
		if err := p.editor.EditTopic(&tele.Chat{ID: chatID}, &tele.Topic{ThreadID: int(dialogID), Name: name}); err != nil {
			slog.ErrorContext(ctx, "topic naming: failed to rename topic", "error", err, "dialog_id", dialogID)
		}
	}()
}

// buildTopicNamingInput renders the first exchange as plain text for TopicNamer. The
// assistant's reply is included when there is one — a turn that ended in an error before
// producing any response still gets named from the user's message alone.
func buildTopicNamingInput(userText, assistantText string) string {
	assistantText = strings.TrimSpace(assistantText)
	if assistantText == "" {
		return userText
	}
	return "User:\n" + userText + "\n\nAssistant:\n" + assistantText
}
